<?php
function report_table(string $heading,array $data):void{echo '<div class="wg-box"><h5>'.h($heading).'</h5><div class="table-scroll"><table class="admin-table">';if($data){echo '<thead><tr>';foreach(array_keys($data[0]) as $k)echo '<th>'.h(ucwords(str_replace('_',' ',$k))).'</th>';echo '</tr></thead><tbody>';foreach($data as $r){echo '<tr>';foreach($r as $v)echo '<td>'.h($v).'</td>';echo '</tr>';}echo '</tbody>';}else echo '<tbody><tr><td>No records for this period.</td></tr></tbody>';echo '</table></div></div>';}
$range=$_GET['range']??'30';$today=date('Y-m-d');$start=match($range){'today'=>$today,'yesterday'=>date('Y-m-d',strtotime('-1 day')),'7'=>date('Y-m-d',strtotime('-6 days')),'month'=>date('Y-m-01'),'last_month'=>date('Y-m-01',strtotime('first day of last month')),default=>date('Y-m-d',strtotime('-29 days'))};$end=$range==='yesterday'?$today:($range==='last_month'?date('Y-m-01'):date('Y-m-d',strtotime('+1 day')));
if($range==='custom'){foreach(['from','to'] as $k){$v=$_GET[$k]??'';$d=DateTime::createFromFormat('!Y-m-d',$v);if(!$d||$d->format('Y-m-d')!==$v){$error='Invalid date range.';break;}}if(!$error&&$_GET['from']<=$_GET['to']){$start=$_GET['from'];$end=date('Y-m-d',strtotime($_GET['to'].' +1 day'));}}
$period=[$start,$end];$days=max(1,(strtotime($end)-strtotime($start))/86400);$previous=date('Y-m-d',strtotime($start.' -'.(int)$days.' days'));
$sales=row('SELECT COUNT(*) orders,COALESCE(SUM(CASE WHEN payment_status="paid" AND status NOT IN ("cancelled","refunded") THEN total ELSE 0 END),0) revenue,COALESCE(AVG(CASE WHEN status NOT IN ("cancelled","refunded") THEN total END),0) average_order FROM orders WHERE created_at>=? AND created_at<?',$period);
$traffic=row('SELECT COUNT(*) sessions,COUNT(DISTINCT visitor_id) visitors FROM analytics_sessions WHERE started_at>=? AND started_at<?',$period);$views=(int)scalar('SELECT COUNT(*) FROM analytics_events WHERE event="page_view" AND created_at>=? AND created_at<?',$period);$oldVisitors=(int)scalar('SELECT COUNT(DISTINCT visitor_id) FROM analytics_sessions WHERE started_at>=? AND started_at<?',[$previous,$start]);$purchaseSessions=(int)scalar('SELECT COUNT(DISTINCT session_id) FROM analytics_events WHERE event="purchase" AND created_at>=? AND created_at<?',$period);$returning=(int)scalar('SELECT COUNT(DISTINCT s.visitor_id) FROM analytics_sessions s JOIN analytics_visitors v ON v.id=s.visitor_id WHERE s.started_at>=? AND s.started_at<? AND v.first_seen<?',[$start,$end,$start]);
?>
<form class="admin-toolbar"><label>Period <select name="range"><?php foreach(['today'=>'Today','yesterday'=>'Yesterday','7'=>'Last 7 days','30'=>'Last 30 days','month'=>'This month','last_month'=>'Last month','custom'=>'Custom'] as $k=>$v): ?><option value="<?= $k ?>" <?= $range===$k?'selected':'' ?>><?= $v ?></option><?php endforeach; ?></select></label><label>From <input type="date" name="from" value="<?= h($start) ?>"></label><label>To <input type="date" name="to" value="<?= h(date('Y-m-d',strtotime($end.' -1 day'))) ?>"></label><button class="tf-button">Apply</button></form>
<div class="metrics-grid"><?php $metrics=['Paid revenue'=>money($sales['revenue']),'Orders'=>$sales['orders'],'Average order value'=>money($sales['average_order']),'Products'=>scalar('SELECT COUNT(*) FROM products WHERE status="publish"'),'Customers'=>scalar('SELECT COUNT(*) FROM users WHERE role="customer"'),'Visitors'=>$traffic['visitors'],'Sessions'=>$traffic['sessions'],'Page views'=>$views,'Pages / session'=>$traffic['sessions']?number_format($views/$traffic['sessions'],2):'0','Returning visitors'=>$returning,'New visitors'=>max(0,$traffic['visitors']-$returning),'Session conversion'=>$traffic['sessions']?round($purchaseSessions/$traffic['sessions']*100,2).'%':'0%','Previous period visitors'=>$oldVisitors,'Visitor change'=>$oldVisitors?round(($traffic['visitors']-$oldVisitors)/$oldVisitors*100,1).'%':'No baseline',"Today’s page views"=>scalar('SELECT COUNT(*) FROM analytics_events WHERE event="page_view" AND created_at>=?',[$today])];foreach($metrics as $label=>$value): ?><div class="wg-box"><div class="body-text"><?= h($label) ?></div><div class="metric-value"><?= h($value) ?></div></div><?php endforeach; ?></div>
<p class="body-text mb-4">Revenue includes paid, non-cancelled, non-refunded orders. Historical imports appear on their original dates. Conversion uses tracked sessions with a purchase event; admin visits and Do Not Track requests are excluded.</p>
<div class="report-grid"><div class="wg-box"><h5>Sales over time</h5><div id="sales-chart"></div></div><div class="wg-box"><h5>Traffic over time</h5><div id="traffic-chart"></div></div>
<?php
report_table('Recent orders',rows('SELECT id,customer_name,total,currency,status,payment_status,created_at FROM orders WHERE created_at>=? AND created_at<? ORDER BY created_at DESC LIMIT 10',$period));
report_table('Order status summary',rows('SELECT status,COUNT(*) orders,SUM(total) order_value FROM orders WHERE created_at>=? AND created_at<? GROUP BY status',$period));
report_table('Low stock',rows('SELECT id,name,stock FROM products WHERE status="publish" AND manage_stock=1 AND stock>0 AND stock<=5 ORDER BY stock LIMIT 10'));
report_table('Out of stock',rows('SELECT id,name,stock FROM products WHERE status="publish" AND (stock_status="outofstock" OR (manage_stock=1 AND stock<=0)) LIMIT 10'));
report_table('Top selling products',rows('SELECT oi.name,SUM(oi.quantity) quantity_sold,SUM(oi.total) sales FROM order_items oi JOIN orders o ON o.id=oi.order_id WHERE o.created_at>=? AND o.created_at<? AND o.status NOT IN ("cancelled","refunded") GROUP BY oi.product_id,oi.name ORDER BY quantity_sold DESC LIMIT 10',$period));
report_table('Top categories (multi-category sales counted per category)',rows('SELECT c.name,SUM(oi.quantity) quantity_sold,SUM(oi.total) sales FROM order_items oi JOIN orders o ON o.id=oi.order_id JOIN product_categories pc ON pc.product_id=oi.product_id JOIN categories c ON c.id=pc.category_id WHERE o.created_at>=? AND o.created_at<? AND o.status NOT IN ("cancelled","refunded") GROUP BY c.id ORDER BY sales DESC LIMIT 10',$period));
report_table('Recent customers',rows('SELECT name,email,created_at,last_login FROM users WHERE role="customer" ORDER BY created_at DESC LIMIT 10'));
report_table('Traffic sources',rows('SELECT CASE WHEN source<>"" THEN source WHEN referrer="" THEN "Direct" WHEN referrer REGEXP "google|bing|yahoo|duckduckgo" THEN "Search" WHEN referrer REGEXP "facebook|instagram|twitter|t.co|linkedin|tiktok" THEN "Social" ELSE referrer END traffic_source,COUNT(*) sessions FROM analytics_sessions WHERE started_at>=? AND started_at<? GROUP BY traffic_source ORDER BY sessions DESC LIMIT 15',$period));
foreach(['device'=>'Devices','browser'=>'Browsers','os'=>'Operating systems','campaign'=>'Campaigns','entry_page'=>'Entry pages','exit_page'=>'Last active pages'] as $dim=>$heading)report_table($heading,rows("SELECT `$dim`,COUNT(*) sessions FROM analytics_sessions WHERE started_at>=? AND started_at<? GROUP BY `$dim` ORDER BY sessions DESC LIMIT 12",$period));
report_table('Popular pages',rows('SELECT page,COUNT(*) views FROM analytics_events WHERE event="page_view" AND created_at>=? AND created_at<? GROUP BY page ORDER BY views DESC LIMIT 12',$period));
report_table('Product views',rows('SELECT p.name,COUNT(*) views FROM analytics_events e JOIN products p ON p.id=e.resource_id WHERE e.event="product_view" AND e.created_at>=? AND e.created_at<? GROUP BY p.id ORDER BY views DESC LIMIT 10',$period));
report_table('Category views',rows('SELECT c.name,COUNT(*) views FROM analytics_events e JOIN categories c ON c.id=e.resource_id WHERE e.event="category_view" AND e.created_at>=? AND e.created_at<? GROUP BY c.id ORDER BY views DESC LIMIT 10',$period));
report_table('Popular articles',rows('SELECT c.title,COUNT(*) views FROM analytics_events e JOIN content c ON c.id=e.resource_id WHERE e.event="blog_view" AND e.created_at>=? AND e.created_at<? GROUP BY c.id ORDER BY views DESC LIMIT 10',$period));
report_table('Funnel events',rows('SELECT event,COUNT(*) events,COUNT(DISTINCT session_id) sessions FROM analytics_events WHERE created_at>=? AND created_at<? AND event IN ("product_view","add_to_cart","begin_checkout","purchase","remove_from_cart") GROUP BY event',$period));
report_table('Searches',rows('SELECT detail search,COUNT(*) events FROM analytics_events WHERE event="search" AND created_at>=? AND created_at<? GROUP BY detail ORDER BY events DESC LIMIT 10',$period));
report_table('Recent traffic',rows('SELECT e.page,e.event,s.device,s.browser,e.created_at FROM analytics_events e JOIN analytics_sessions s ON s.id=e.session_id WHERE e.created_at>=? AND e.created_at<? ORDER BY e.id DESC LIMIT 15',$period));
?>
</div>
<?php $salesDaily=rows('SELECT DATE(created_at) day,COALESCE(SUM(CASE WHEN payment_status="paid" AND status NOT IN ("cancelled","refunded") THEN total ELSE 0 END),0) revenue,COUNT(*) orders FROM orders WHERE created_at>=? AND created_at<? GROUP BY DATE(created_at) ORDER BY day',$period);$trafficDaily=rows('SELECT DATE(created_at) day,COUNT(*) views FROM analytics_events WHERE event="page_view" AND created_at>=? AND created_at<? GROUP BY DATE(created_at) ORDER BY day',$period); ?>
<script src="<?= url('admin/js/apexcharts/apexcharts.js') ?>"></script><script>const sales=<?= json_encode($salesDaily,JSON_HEX_TAG) ?>,traffic=<?= json_encode($trafficDaily,JSON_HEX_TAG) ?>;new ApexCharts(document.querySelector('#sales-chart'),{chart:{type:'area',height:280},series:[{name:'Paid revenue',data:sales.map(r=>Number(r.revenue))}],xaxis:{categories:sales.map(r=>r.day)},noData:{text:'No sales in this period'}}).render();new ApexCharts(document.querySelector('#traffic-chart'),{chart:{type:'bar',height:280},series:[{name:'Page views',data:traffic.map(r=>Number(r.views))}],xaxis:{categories:traffic.map(r=>r.day)},noData:{text:'No traffic in this period'}}).render();</script>
